mapper.select:
SELECT a.comment_id,a.quote_text AS exact,a.quote_prefix AS prefix,a.quote_suffix AS suffix,
       a.start_offset AS `start`,a.end_offset AS `end`,a.content_hash
FROM article_comment_anchor a INNER JOIN comment c ON c.comment_id=a.comment_id
WHERE c.article_id=#{articleId} AND c.status=0 AND c.parent_id=0 AND c.comment_id > #{afterId}
ORDER BY c.comment_id LIMIT #{limit}
